def backfill_matriculas(apps, schema_editor):
    """Crea una Matricula para cada estudiante existente a partir de sus campos legacy."""
    Estudiante = apps.get_model("usuarios", "Estudiante")
    Matricula = apps.get_model("usuarios", "Matricula")
    ConfiguracionInstitucional = apps.get_model("core", "ConfiguracionInstitucional")

    cfg = ConfiguracionInstitucional.objects.first()
    anio_lectivo = cfg.anio_lectivo_activo if cfg else 2026

    matriculas = []
    for est in Estudiante.objects.all().iterator():
        # Evitar duplicados si la migración corre más de una vez
        if Matricula.objects.filter(estudiante=est, anio_lectivo=anio_lectivo).exists():
            continue
        # Determinar año a partir del código de matrícula si es posible
        anio = anio_lectivo
        codigo = est.codigo_matricula
        if codigo and len(codigo) >= 4 and codigo[:4].isdigit():
            anio_candidato = int(codigo[:4])
            if 2000 <= anio_candidato <= 2100:
                anio = anio_candidato
        matriculas.append(
            Matricula(
                estudiante=est,
                seccion=est.seccion_obj,
                anio_lectivo=anio,
                codigo_matricula=codigo,
                situacion=est.situacion_matricula or "matriculado",
                fecha_matricula=est.fecha_ingreso,
            )
        )
        if len(matriculas) >= 500:
            Matricula.objects.bulk_create(matriculas)
            matriculas = []
    if matriculas:
        Matricula.objects.bulk_create(matriculas)


